        return np.clip(candidate, lb, ub)

    def evaluate(x):
        return func(clip(x))

    x = np.random.uniform(-5.0, 5.0, (1, dim))
    c = np.eye(dim)
    mu = np.zeros((1, dim))
    sigma = 1.0
    n_evals = 0

    while n_evals < budget:
        y = evaluate(x)

